gY9(){return"\u0637\u0627\u0644\u0628\u0629"},
gY8(){return"\u0622\u064a\u0629 \u0645\u062d\u0645\u062f"},
gVL(){return"\u270d\ufe0f \u0645\u062f\u0648\u0646\u062a\u064a"},
gVM(){return"\u0627\u0642\u0631\u0623 \u0623\u0641\u0643\u0627\u0631\u064a \ud83d\udcad\u060c"},
gVN(){return"\u0627\u0628\u0642\u064e \u0645\u0648\u0627\u0643\u0628\u064b\u0627 \ud83c\udf0d."},
gVO(){return"\u0645\u0646 \u062f\u0631\u0648\u0633 \u0645\u0633\u062a\u0641\u0627\u062f\u0629 \ud83d\udcda \u0625\u0644\u0649 \u0623\u0641\u0643\u0627\u0631 \u062a\u0633\u062a\u062d\u0642 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \ud83d\udca1\u060c \u0645\u062f\u0648\u0646\u062a\u064a \u0647\u064a \u0627\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u064a\u0644\u062a\u0642\u064a \u0641\u064a\u0647 \u0627\u0644\u0625\u0628\u062f\u0627\u0639 \u0628\u0627\u0644\u0633\u0631\u062f \ud83d\udd25."},
goS(){return"\u0627\u0642\u0631\u0623 \u0627\u0644\u0645\u0632\u064a\u062f"},
gYJ(){return"\ud83d\udcb8 \u062a\u0633\u0639\u064a\u0631 \u0634\u0641\u0627\u0641 \u0648\u0645\u062f\u0631\u0648\u0633"},
gYK(){return"\u062a\u0642\u062f\u064a\u0631 \u0633\u0631\u064a\u0639 \u0644\u062a\u0643\u0644\u0641\u0629 \u0645\u0634\u0631\u0648\u0639\u0643 \u26a1."},
